from author import *
c =C ('数列、递推与数学归纳法')
L (c ,'用下标记录一列数',('从1开始编号',r'$a_1=3,\quad a_2=5,\quad a_3=7'),('通项与递推',r'$a_n=2n+1,\qquad a_{n+1}=a_n+2'),
'数列是一列按位置排列的数，下标表示第几个位置，而不是乘法。这里第一项三，第二项五，第三项七。可以用一个直接表达式算第n项，也可以给出起点，再说明下一项怎样由前一项得到。前者叫通项，后者叫递推。题目可能从零编号，也可能从一编号，所以第一步一定先看下标起点，别把同一个公式直接套到不同起点上。',
'现在从第一项开始，每次加二，依次得到三、五、七、九。递推除了更新规则，还必须有足够的初始条件，否则会出现很多不同的数列都满足同一条关系。比如每次加二，起点一和起点三都会符合，但得到的数列不同。求出通项后，应先代入前两项核对，再检查它是否满足递推，而不是只凭数值看起来像就宣布答案正确。',['下标记录位置，不是乘法','先看从0还是从1编号'],['递推要配足初始条件','通项同时核对起点与更新规则'],visual =V ('sequence',mode ='linear'),anchors =[None ,'现在从第一项开始'])
L (c ,'一阶递推的展开',('初始条件',r'$a_1=2,\quad a_{n+1}=2a_n+1'),('前几项与平移',r'$2,5,11,23;\qquad b_n=a_n+1'),
'若下一项等于前一项乘二再加一，第一项是二，先按顺序算出五、十一、二十三。这个过程没有复杂技巧，先把每次更新都写出来，能避免漏掉常数项。展开两步会发现旧项每次多乘一个二，同时不断增加一、二、四这样的贡献。递推题不必总从背公式开始，先算小规模，再观察重复出现的结构。',
'这里可以给每项都加一，把新数列记成b。下一项加一以后，正好等于前一项加一的两倍，因此b成为首项三、公比二的等比数列。于是原数列第n项是三乘二的n减一次方，再减一。这个平移方法适用于当前形式，不是说所有递推都加一就行。最后代回第一项和更新式，两个检查都通过，才说明候选通项确实符合条件。',['先逐步代入，观察结构','常数项不能漏'],['加1后变为等比数列','结果要回代起点与递推'])
L (c ,'二阶递推与斐波那契',('两个初始值',r'$F_0=0,\quad F_1=1,\quad F_n=F_{n-1}+F_{n-2}'),('逐步展开',r'$0,1,1,2,3,5,8'),
'有的下一项同时依赖前面两项，因此只给一个初始值不够。斐波那契数列从零和一开始，后面的每项等于前两项之和。先得到一，再得到二、三、五、八。画面把前两个位置连到新位置，说明这次更新需要哪两份信息。写递推时要标明适用下标，不能在前两项还没有定义时就向前取不存在的项。',
'台阶问题也会出现同样结构。一次走一级或两级，到第n级的最后一步只能来自第n减一级，或者第n减二级，两类走法不重叠，所以数量相加。但它的初始条件要按具体问题确定，不能看到前两项相加，就机械抄斐波那契的零和一。递推关系负责拆问题，初始条件负责锁定实际问题，两者共同决定答案。',['依赖前两项就要两个起点','明确递推从哪个下标开始'],['按最后一步分成互斥情况','相同递推可有不同初始条件'],visual =V ('sequence',mode ='fib'),anchors =['画面把前两个位置连到新位置',None ])
L (c ,'数学归纳法的两步',('起点',r'$P(1)\text{ is true}'),('推进',r'$P(k)\Longrightarrow P(k+1)\quad(k\geq1)'),
'想证明一个结论对所有正整数成立，不能只算前三个就结束。数学归纳法需要两部分：先证明起点成立，再证明只要第k步成立，就能推出下一步成立。可以想成一排有规则连接的多米诺，第一块倒下，以及每块能推倒下一块，这两个条件合起来才覆盖整排。这里的图帮助理解步骤，正式答案仍需写出具体等式或推理。',
'归纳假设只是为了完成从k到k加一这一段推导，不能直接把目标结论当作已经对所有整数成立。起点也可能是零、二或者更大的数，要与题目范围一致。若只能从偶数推到下一个偶数，就不能声称已经覆盖全部整数。检查证明时分别问，起点有没有落地，推进有没有跨出新的一步，是否覆盖题目要求的每一个下标。',['起点与推进缺一不可','不是检查几个例子就结束'],['归纳假设只用于推进','下标范围与步长要覆盖目标'],visual =V ('induction'),anchors =['先证明起点成立','推进有没有跨出新的一步'])
L (c ,'归纳证明求和公式',('假设',r'$1+2+\cdots+k=\frac{k(k+1)}2'),('补上新项',r'$\frac{k(k+1)}2+(k+1)=\frac{(k+1)(k+2)}2'),
'证明一加到n等于n乘n加一再除以二，先看n等于一，左右都为一。再假设加到k时公式成立，目标是处理加到k加一。把旧的求和整体换成归纳假设，然后补上新的一项k加一。注意新项是加在原有求和后面，不能直接把原公式中的k换成k加一就说证明完成，那只是把要证明的目标重写了一遍。',
'把两项通分，再提出共同因子k加一，就得到k加一乘k加二再除以二，正好是目标形式。写证明时可以分四行：起点、归纳假设、加新项、化成目标。反过来从目标式变形，也许能帮助找思路，但正式推导必须说明为什么每一步有依据。归纳法的得分关键是旧结论怎样真正帮助得到新结论，而不是只写假设和所以两句话。',['先验证起点，再明确归纳假设','补上新项而不是照抄目标'],['提出共同因子得到下一步','写出旧结论到新结论的连接'])
Q (c ,'递推与归纳练习',('递推',r'$a_1=1,\quad a_{n+1}=a_n+3'),('问题','求第4项；只验证前4项能否证明通项'),
'第一项是一，后面每项等于前一项加三。请算出第四项，再判断，验证前四项都满足三n减二，能不能证明这条通项对全部正整数都成立。第一问顺着递推走，第二问想一想，有限次核对与覆盖全部下标之间还差哪一个证明步骤。接下来留四秒思考。',
'四项依次是一、四、七、十，所以第四项是十。前四项核对通过，只能检查这些位置，不能证明全部正整数。可以再用归纳法，先验证n等于一，再假设第k项等于三k减二，加三以后得到三乘k加一再减二，完成推进。算出规律与证明规律是两件相关但不同的工作。',('数值',r'$a_4=10'),('证明','有限核对不足；还需对一般k完成推进'))

c =C ('图与图的基本问题')
L (c ,'顶点、边与度数',('简单无向图',r'$V=\{A,B,C,D\},\ E=\{AB,BC,CD,DA,AC\}'),('握手定理',r'$\sum_{v\in V}\deg(v)=2|E|'),
'把城市画成点，把两城之间的直接道路画成线，就得到图。点叫顶点，连接叫边。今天先讨论简单无向图，不带自环，同一对点之间没有重复边。一个顶点接着多少条边，叫它的度。图的形状可以拉伸、旋转，只要连接关系不变，就是在表达同一结构；画面上的两条线交叉，也不自动代表那里多了一个顶点。',
'现在逐条加入五条边。四个顶点的度依次是三、二、三、二，加起来十，正好等于边数五的两倍，因为每条边在两个端点各贡献一次。这叫握手定理。由此可以推出，奇数度顶点的个数必须是偶数。题目给一串度数时，先检查总和是否为偶数，这能排除一些不可能情况，但总和为偶数还不保证一定存在所要求的简单图。',['图的连接关系比摆放位置重要','线交叉不自动产生顶点'],['每条无向边贡献两个度','度数总和为偶数只是必要检查'],visual =V ('graph',mode ='degrees'),anchors =[None ,'现在逐条加入五条边'])
L (c ,'路径、回路与连通',('路径','依次沿边经过顶点；是否允许重复要看题目术语'),('连通','任意两点之间存在路径'),
'从A出发，沿着已有的边走到B，再到C，就得到一段行走。离散数学中，途径、迹、路这些中文术语在教材之间有些差异，做题要看题目是否允许重复边和重复顶点。本课说简单路径时，要求顶点不重复；简单回路则首尾重合，中间顶点不重复。先写清允许什么，再数长度，长度通常按经过的边数计算。',
'无向图连通，表示任意两点之间都能通过某条路径到达，不要求它们直接有边。如果分成几块，块内互相可达，块间无法到达，每一块叫连通分量。现在从一个起点逐层寻找能到达的顶点，所有点都被找到就说明这张无向图连通。有向图还要考虑方向，单向能走到不等于互相可达，不能直接照搬无向图的判断。',['长度通常数经过的边','简单路径不重复顶点'],['连通允许经过中间顶点','有向图必须沿箭头走'],visual =V ('graph',mode ='bfs'),anchors =[None ,'现在从一个起点逐层寻找'])
L (c ,'邻接矩阵与图的表示',('邻接矩阵','行表示出发点，列表示到达点；有边记1'),('简单无向图','矩阵关于主对角线对称；主对角线为0'),
'图也可以写成一个方形的零一表，行列使用同一份顶点顺序。如果A与B之间有边，就在A行B列填一。简单无向图没有方向，所以反过来的B行A列也要是一；没有自环，所以对角线都是零。顶点顺序换了，矩阵的行列位置会一起换，但图的实际连接不一定改变。转表示前先把顺序写在旁边。',
'若需要频繁找某个点连着谁，也可以为每个顶点保存一个邻居清单，叫邻接表。矩阵直观看出任意两点是否相邻，邻接表则把实际存在的邻居列出来。两种表示都要与边清单对应。对于当前四点五边的图，每行一的个数就是对应顶点的度；但若换成有向图，行和列分别对应出度与入度，含义要重新确认。',['矩阵行列顺序必须一致','无向图矩阵对称'],['邻接表直接列出邻居','有向图行列度数含义不同'],visual =V ('adjacency'),anchors =['在A行B列填一',None ])
L (c ,'欧拉与哈密顿',('欧拉问题','每条边恰走一次；回路还要回到起点'),('判定条件','有边部分连通；欧拉回路全偶，开放迹恰2个奇度点'),
'一笔画问题常问能不能把每条边恰好走一次，这叫欧拉问题。若还要求回到起点，就是欧拉回路。在无向图中，忽略没有边的孤立点后必须连通；全体顶点度数都为偶数时有欧拉回路，恰有两个奇数度顶点时有一条起终点不同的欧拉迹。进入中间点通常要再离开，所以边在中间点成对使用，这能帮助你记住条件。',
'当前四点五边的图，A和C是两个奇数度点，因此可以从A出发到C结束，把每条边走一次；却不能要求回到A。另一类题目要求每个顶点恰好经过一次，叫哈密顿问题，它关注顶点而不是边。不要把欧拉的奇偶度数条件直接套过去。相似的路线图，问的是边还是点，可能需要完全不同的判断方法。',['欧拉关注每条边一次','连通条件不能漏'],['两个奇度点作为开放路线两端','哈密顿关注点，不照套欧拉条件'],visual =V ('graph',mode ='euler'),anchors =[None ,'可以从A出发到C结束'])
L (c ,'最短路、二分图与平面图',('带权最短路','最少边数与最小总权重不是同一个目标'),('两条常用性质','二分图无奇环；连通平面嵌入满足V减E加F等于2'),
'道路图上每条边写一个距离，路线总长度就要把边权加起来，边数最少的路未必距离最短。现在比较A到D的两条路线，直接边权重八，经过B和C的三条边总权重六，所以后者更短。非负权图可以使用迪杰斯特拉算法，若有负权就不能直接依赖同样的贪心规则。今天先明确优化目标与条件，不展开完整算法证明。',
'图还可以研究分类与画法。二分图能把顶点分成两组，让每条边都跨组连接，它等价于没有奇数长度回路。平面图则要求能在平面上画到边不交叉，不是说当前画得交叉就一定不是平面图。连通平面嵌入满足顶点数减边数加面数等于二，最外面的区域也算一个面。公式里的条件和面数的含义，都要一起记住。',['最短路先明确边数还是权重和','迪杰斯特拉要求非负权'],['二分图检查有无奇环','平面公式的面包含外部区域'],visual =V ('graph',mode ='weighted'),anchors =['现在比较A到D的两条路线',None ])
Q (c ,'边数与一笔画',('度数',r'$3,2,3,2'),('已知','简单无向图连通；求边数与欧拉回路是否存在'),
'一个连通简单无向图有四个顶点，度数依次为三、二、三、二。它有多少条边，是否存在把所有边走一次并回到起点的欧拉回路。如果只能找到不回起点的欧拉迹，它的两个端点应是哪一类顶点。先计算度数总和，再检查奇度点数，接下来留四秒。',
'度数和是十，每条边贡献两个度，所以共有五条边。两点度数是三，为奇数，因此不存在欧拉回路；在已知连通的条件下，存在一条开放欧拉迹，两个端点就是这两个奇数度顶点。注意连通条件已经由题目提供，如果没有这项信息，只检查度数奇偶还不能完整判断。',('边数',r'$|E|=(3+2+3+2)/2=5'),('路线','无欧拉回路；开放迹以两个奇度点为端点'))

c =C ('树、生成树与编码')
L (c ,'树是连通且无回路的图',('无向树','连通；没有回路'),('有限树的边数',r'$|E|=|V|-1'),
'树可以先看成一种特别节省连线的连接结构。它把所有顶点连在一起，又没有回路。这里的树是无向图意义下的树，尚未指定谁是根。若有n个顶点，它恰有n减一条边。比如五个顶点的树只有四条边，每增加一条连接新顶点的边，才能把规模往外扩展，同时不制造回路。先把连通与无回路两个条件一起记住。',
'树中任意两点之间恰好只有一条简单路径。若出现两条不同路径，就能沿其中一条去、另一条返回，组成回路。删掉树里任意一条边，会把它分成两块；在原有顶点之间补一条新边，又会制造一个回路。这些性质在题目中常用来互相检查。但只看到边数等于顶点数减一，还需要配合连通或无回路等条件，不能单独认定为树。',['树同时连通且无回路','n个点有n减1条边'],['两点间简单路径唯一','边数条件不能单独使用'],visual =V ('tree',mode ='basic'),anchors =['每增加一条连接新顶点的边',None ])
L (c ,'根、父子与遍历',('有根树','指定一个根，按离根远近确定父子关系'),('遍历','前序：先根后孩子；后序：先孩子后根'),
'给一棵树指定根之后，边就有了向下展开的层次。离根更近的相邻点叫父节点，更远的叫孩子，没有孩子的点叫叶子。层数从零还是一开始，题目要先约定。根是观察层次的起点，不是说其他顶点从此不能作为路径起点；同一棵无向树换一个根，父子关系可能改变，但原有连接仍然相同。',
'遍历是按规则把节点访问一遍。先访问根，再依次访问各棵子树，叫前序；先完成孩子对应子树，再访问根，叫后序。现在按左到右约定走前序，节点依次亮起。中序通常用于有左右位置区别的二叉树，不要给一般多叉树随意套同一个中序规则。题目给遍历序列时，先确认树的类型和孩子访问顺序，再判断结果。',['根决定层次与父子关系','叶子指没有孩子'],['前序先根，后序后根','访问左右顺序先约定'],visual =V ('tree',mode ='preorder'),anchors =[None ,'现在按左到右约定走前序'])
L (c ,'生成树与最小生成树',('生成树','保留原图所有顶点，选取部分边构成树'),('最小生成树','在所有生成树中，使边权总和最小'),
'连通图里可能有多余回路，只保留一些边，仍然连接全部顶点并且没有回路，就得到生成树。它必须保留所有顶点，不能为了减少边把某个点丢掉。生成树一般不唯一，顶点数固定后，每棵都恰好有n减一条边。这里最少边数只是树的共同性质，不表示带权情形下这些树的造价都一样。',
'若边上有造价，最小生成树要让总造价尽可能小。可以按边权从小到大尝试加入，只要不产生回路就保留，这就是克鲁斯卡尔方法的基本步骤。现在依次选权重一、二、三的三条边，连接四个点，总权重六。最小生成树关注连通全体的总费用，与从某个起点到各点的最短路径树目标不同，两种最小不能混为一谈。',['生成树必须覆盖全部顶点','同一图可有多棵生成树'],['按小权边加入且避免成环','总费用最小不等于起点最短路'],visual =V ('graph',mode ='mst'),anchors =[None ,'现在依次选权重一、二、三'])
L (c ,'二叉树与前缀编码',('前缀要求','任何码字都不是另一码字的开头'),('合法编码例子',r'$A:0,\quad B:10,\quad C:11'),
'在二叉树中，每个节点最多两个孩子，可以把向左的边记零，向右的边记一，从根到某个叶子的路径就形成一串编码。把字符都放在叶子上，就能让任何一个完整码字都不是另一码字的开头，叫前缀编码。这里A用零，B用一零，C用一一。连续收到编码时，走到叶子就认出一个字符，再回到根处理后面的位。',
'比如零一零一一，可以从左到右解成A、B、C。因为零已经是一个完整叶子码字，其他字符就不能再使用零开头的更长码字，否则无法保证同样的即时识别方式。前缀编码允许字符长度不同，却通过结构避免边界歧义。判断是否合法，可以看有没有一个字符串正好是另一个字符串的前缀，而不是只检查码字彼此不相等。',['二叉边记0和1，叶子放字符','完整码字不能是别人的前缀'],['变长编码也可以清晰识别','仅码字不同还不足够'],visual =V ('code_tree'),anchors =['这里A用零，B用一零，C用一一',None ])
L (c ,'哈夫曼编码的合并步骤',('频数',r'$A:5,\quad B:2,\quad C:1'),('每次合并最小两项',r'$1+2=3,\qquad3+5=8'),
'字符出现得越频繁，若能给它较短的码字，平均使用位数就可能减少。哈夫曼算法从各字符的频数开始，每次选最小的两个，合成一个新节点，再放回候选集合继续比较。这里一与二先合成三，三再与五合成八。频数是权重，不是直接作为字符编码里的数字，树边仍然可以标零和一。',
'最后频数五的A深度一，另外两个字符深度二，带权路径长度是五乘一，加二乘二，加一乘二，等于十一。交换左右孩子会改变具体码字，却不会改变这些长度和总权重；出现同权时，也可能存在不同但同样最优的树。计算时要每次从当前候选中选最小两项，不能把一开始排好的名单固定后就机械两两合并。',['反复选择当前最小两项','新节点需要放回比较'],['本例带权路径长度为11','左右交换不改变编码长度'],visual =V ('huffman'),anchors =['这里一与二先合成三',None ])
Q (c ,'树的边数与前缀判断',('问题一','8个顶点的树有几条边'),('问题二','编码0、01、11是否为前缀编码'),
'一棵无向树有八个顶点，它有多少条边。另外，三个字符分别使用零、零一、一一作为编码，这是不是前缀编码。第一问使用树的基本性质，第二问逐个比较一个码字是否出现在另一码字的开头。两问的条件不同，请分别判断，接下来留四秒思考。',
'树有七条边，因为有限树的边数等于顶点数减一。给出的编码不是前缀编码，因为零是零一的前缀，读到第一个零时，无法按叶子即时结束规则判断它是完整第一个字符，还是第二个字符的开头。这里指出的是前缀性质不满足，不需要进一步声称所有非前缀编码都必然不可能以其他方式唯一解码。',('答案',r'$|E|=8-1=7'),('编码','不是前缀编码：0是01的前缀'))
